// J5 compatibility: honest history signed by old Gateway builds, read by the new client code.
// usage: tsx consume.mts <producer.json> <path to new protocol src/index.ts>
import { readFileSync } from "node:fs";
const [file, impl] = process.argv.slice(2);
const p = await import(impl!);
const { steps, rootPub } = JSON.parse(readFileSync(file!, "utf8"));
const host = steps[0].binding.body.hostname;
let failures = 0;
const show = (o: unknown) => JSON.stringify(o);
async function verified(i: number, pin: any) {
  const check = await p.verifyBindingForPin(
    { root_pub: rootPub, binding: steps[i].binding }, pin, { host, now: steps[i].at });
  if (!check.ok) throw new Error(`binding ${i}: ${show(check)}`);
  return check;
}
async function run(from: number, stored: any, pin: any, label: string) {
  for (let i = from; i < steps.length; i++) {
    const check = await verified(i, pin);
    pin = check.pin;
    const a = await p.assessFreshness({ snapshot: steps[i].snapshot },
      { binding: check.binding, stored, now: steps[i].at, policy: "enforce" });
    const ok = a.verdict.ok && a.verdict.fresh;
    if (!ok) failures++;
    console.log(`  ${label} step ${i} (${steps[i].label}): ${ok ? "ok fresh" : "FAIL " + show(a.verdict)} -> ${show(a.state.snapshot)}`);
    stored = a.state;
  }
}
const rootFp = await p.fingerprint(rootPub);
const firstPin = { claw_id: steps[0].binding.body.claw_id, root_fp: rootFp, binding_seq: 0 };
console.log("A. new client from scratch");
await run(0, null, firstPin, "new");
console.log("B. state saved by the old client, loaded by the new one (clamp on load), then continued");
for (let i = 0; i < steps.length - 1; i++) {
  const legacy = steps[i].oldState;
  const pinSeq = steps[i].binding.body.binding_seq;
  const loaded = p.clampFreshnessState(legacy, pinSeq);
  const asDesigned = loaded.snapshot.binding_seq === legacy.snapshot.binding_seq &&
    loaded.snapshot.seq === 0 && loaded.snapshot.issued_at === 0 && loaded.snapshot.k_gw === undefined;
  if (!asDesigned) failures++;
  console.log(` old state after step ${i}: ${show(legacy.snapshot)} -> loaded ${show(loaded.snapshot)} (pin ${pinSeq}) ${asDesigned ? "binding_seq kept, order dropped" : "UNEXPECTED"}`);
  const pin = { ...firstPin, binding_seq: pinSeq, k_gw: steps[i].binding.body.k_gw };
  await run(i + 1, loaded, pin, "upgraded");
}
console.log(failures ? `FAILURES: ${failures}` : "all verdicts ok fresh; no snapshot_ahead; stored state clamped only as designed");
process.exit(failures ? 1 : 0);
