// Honest Gateway history signed by THIS tree's own code (publisher.ts publishClaw + protocol),
// and the freshness state THIS tree's client code stores after each step.
import { publishClaw } from "./src/gateway/openclaw-id/publisher.ts";
import { assessFreshness } from "./packages/openclaw-id-protocol/src/freshness/freshness.ts";
import { signStatement } from "./packages/openclaw-id-protocol/src/index.ts";
import { buildWorld, certBody, signChange, mustApply, WORLD_NOW, worldKey } from "./packages/openclaw-id-protocol/src/testing/world.ts";

const w = await buildWorld();
const steps: { label: string; binding: unknown; snapshot: unknown; at: number; oldState: unknown; oldVerdict: unknown }[] = [];
let state = w.state;
let binding = w.binding;
let t = WORLD_NOW;
let stored: unknown = null;
const realNow = Date.now;
async function publish(label: string) {
  Date.now = () => t * 1000;
  let snap: unknown;
  const client = {
    registerClaw: async () => ({ owner_account_id: "acct-owner" }),
    publishDescriptor: async () => {},
    publishSnapshot: async (_id: string, s: unknown) => { snap = s; },
  };
  const out = await publishClaw({
    record: { claw_id: w.state.claw_id, authority: state, binding,
      discovery: { owner_account_id: "acct-owner", published_binding_seq: binding.body.binding_seq } } as never,
    relayUrl: "https://relay.example/", client: client as never, signer: w.gateway.signer,
  });
  Date.now = realNow;
  if (out.state !== "published") throw new Error(`${label}: ${JSON.stringify(out)}`);
  const a = await assessFreshness({ snapshot: snap }, { binding: binding.body, stored: stored as never, now: t + 5, policy: "enforce" });
  stored = a.state;
  steps.push({ label, binding, snapshot: snap, at: t + 5, oldState: a.state, oldVerdict: a.verdict });
}
await publish("link: binding 1, membership seq 2");
t += 1800; await publish("hourly republish (same seq, newer issued_at)");
const d3 = await worldKey("device-3");
const cert3 = await signStatement("OwnerDeviceCert", certBody(d3), w.device1.signer);
state = await mustApply(state, await signChange(state, w.device1.signer, { op: "add_owner_device", cert: cert3 }), "tunnel");
t += 600; await publish("membership change");
// Honest K_srv rotation: owner R signs binding 2 with the same K_gw (what old Gateways can do).
const srv2 = await worldKey("server-2");
binding = await signStatement("ServerBinding", { ...w.binding.body, k_srv: srv2.peer, binding_seq: 2, issued_at: t }, w.root);
t += 60; await publish("K_srv rotation: binding 2");
t += 3000; await publish("republish at binding 2");
console.log(JSON.stringify({ rootPub: w.rootPub, steps }));
```
